\maketitle

\begin{abstract}
A hypergraph is \emph{linear} (equivalently, a \emph{partial Steiner system})
when any two distinct edges share at most one vertex. For a linear $r$-uniform
hypergraph on $n$ vertices with $m$ edges, an elementary double count yields the
\emph{packing bound} $m\binom{r}{2}\le\binom{n}{2}$, equivalently the density
threshold $m\le n(n-1)/(r(r-1))$ with leading coefficient $1/(r(r-1))$. It is
classical that a Steiner system $S(2,r,n)$ attains equality, certifying that the
coefficient cannot be improved. We sharpen this one-sided optimality into a
complete characterization of the extremal configurations. We prove that the
packing bound is an equality \emph{if and only if} the hypergraph covers every
pair of vertices, i.e.\ is a Steiner system (Theorem~\ref{thm:global}). We then
develop the local (per-vertex) analogue: each vertex satisfies
$\deg(v)(r-1)\le n-1$ (Theorem~\ref{thm:local}), with equality \emph{if and only
if} the edges through $v$ cover every other vertex (Theorem~\ref{thm:localtight}).
As a corollary, every covering linear $r$-uniform hypergraph is degree-regular
with $\deg(v)=(n-1)/(r-1)$ for all $v$ (Theorem~\ref{thm:regular}): tightness is
global \emph{and} local simultaneously. We illustrate with the Fano plane
$S(2,3,7)$, the minimal simultaneously-tight witness, and relate the results to
the $e=2$ boundary of the Brown--Erd\H{o}s--S\'os extremal function. All results
have been formally verified.
\end{abstract}

\section{Introduction}

\subsection{Background and motivation}
Let $V$ be a finite set of $n$ \emph{vertices}. An \emph{$r$-uniform hypergraph}
on $V$ is a family $\E$ of $r$-element subsets of $V$, called \emph{edges}; we
write $m=|\E|$. The hypergraph is \emph{linear} if every two distinct edges
intersect in at most one vertex. Linear hypergraphs generalize simple graphs
($r=2$) and coincide with \emph{partial linear spaces}: vertices are points,
edges are lines, two lines meet in at most one point.

Linearity is the cleanest density constraint in extremal hypergraph theory. It is
the $e=2$ boundary of the Brown--Erd\H{o}s--S\'os (BES) programme, the case in
which the relevant overlap involves two vertices: ``no pair of vertices is
covered twice,'' which is exactly the defining property of a linear hypergraph.
Pinning down the extremal configurations at this boundary anchors the broader
sparse-hypergraph literature.

The fundamental quantitative fact is the \emph{packing bound}: since the edges
are pairwise pair-disjoint,
\begin{equation}\label{eq:packing}
  m\binom{r}{2}\le\binom{n}{2}.
\end{equation}
A \emph{Steiner system} $S(2,r,n)$ --- a linear $r$-uniform family covering every
pair (necessarily exactly once) --- attains equality in \eqref{eq:packing},
certifying that $1/(r(r-1))$ is optimal whenever such a system exists.

\subsection{Contribution}
The classical statement gives only one direction of optimality (an extremal
configuration \emph{exists}). We close the gap:
\begin{enumerate}
  \item \textbf{Global tightness} (Theorem~\ref{thm:global}): equality in
  \eqref{eq:packing} holds iff the hypergraph covers every pair (is Steiner).
  \item \textbf{Local packing bound} (Theorem~\ref{thm:local}):
  $\deg(v)(r-1)\le n-1$ for every vertex $v$.
  \item \textbf{Local tightness} (Theorem~\ref{thm:localtight}): equality iff
  the link of $v$ covers every other vertex.
  \item \textbf{Simultaneous rigidity} (Theorem~\ref{thm:regular}): every Steiner
  system is degree-regular with $\deg(v)=(n-1)/(r-1)$.
\end{enumerate}
The proofs rest on one reusable principle: \emph{a disjoint family of subsets
fills its ambient set iff its total cardinality equals that of the ambient set},
applied once globally (to pairs) and once locally (to the link of a vertex).

\section{Definitions}
Throughout $V$ is finite with $|V|=n$, edges are finite subsets of $V$, and
$\Ptwo(S)$ denotes the family of $2$-element subsets of $S$, so
$|\Ptwo(S)|=\binom{|S|}{2}$.

\begin{definition}[Uniformity]
A family $\E$ is \emph{$r$-uniform} if $|e|=r$ for every $e\in\E$.
\end{definition}
\begin{definition}[Linearity]
$\E$ is \emph{linear} if $|e_1\cap e_2|\le 1$ for all distinct $e_1,e_2\in\E$.
\end{definition}
\begin{definition}[Covering]
$\E$ \emph{covers} all pairs if for every $p\in\Ptwo(V)$ there is $e\in\E$ with
$p\subseteq e$.
\end{definition}
\begin{definition}[Steiner system]
A \emph{Steiner system} $S(2,r,n)$ is an $r$-uniform linear family on $n$
vertices covering all pairs. In a linear covering family each pair is covered
exactly once.
\end{definition}
\begin{definition}[Degree, link]
The \emph{degree} of $v$ is $\deg(v)=|\{e\in\E:v\in e\}|$; the family
$L_v=\{e\in\E:v\in e\}$ is the \emph{link} of $v$.
\end{definition}

\section{The pair-disjointness engine}
For an edge $e$ let $\Ptwo(e)$ be the family of its $2$-subsets; for an $r$-edge,
$|\Ptwo(e)|=\binom{r}{2}$.

\begin{lemma}[Pair-disjointness]\label{lem:disjoint}
If $\E$ is linear, then $\{\Ptwo(e)\}_{e\in\E}$ are pairwise disjoint.
\end{lemma}
\begin{proof}
A common pair $p\in\Ptwo(e)\cap\Ptwo(f)$ gives $p\subseteq e\cap f$, so
$|e\cap f|\ge 2$, contradicting linearity for $e\ne f$.
\end{proof}

\begin{lemma}[Containment]\label{lem:contain}
For any $\E$, $\bigcup_{e\in\E}\Ptwo(e)\subseteq\Ptwo(V)$.
\end{lemma}
\begin{proof}
A $2$-subset of $e\subseteq V$ is a $2$-subset of $V$.
\end{proof}

\begin{lemma}[Pair count]\label{lem:count}
If $\E$ is $r$-uniform and linear, then
$\bigl|\bigcup_{e\in\E}\Ptwo(e)\bigr|=m\binom{r}{2}$.
\end{lemma}
\begin{proof}
By Lemma~\ref{lem:disjoint} the union is disjoint, so its size is
$\sum_{e\in\E}|\Ptwo(e)|=m\binom{r}{2}$ by $r$-uniformity.
\end{proof}

Lemmas~\ref{lem:contain}--\ref{lem:count} reprove \eqref{eq:packing}.

\section{Global tightness characterization}
\begin{theorem}[Global tightness]\label{thm:global}
Let $\E$ be an $r$-uniform linear hypergraph on $V$, $|V|=n$, with $m$ edges.
Then
\[
  m\binom{r}{2}=\binom{n}{2}\iff \E\text{ covers every pair of }V,
\]
i.e.\ equality holds exactly when $\E$ is a Steiner system $S(2,r,n)$.
\end{theorem}
\begin{proof}
Let $U=\bigcup_{e\in\E}\Ptwo(e)$. By Lemma~\ref{lem:count} $|U|=m\binom{r}{2}$,
and by Lemma~\ref{lem:contain} $U\subseteq\Ptwo(V)$ with
$|\Ptwo(V)|=\binom{n}{2}$. The crux is
\begin{equation}\label{eq:seteq}
  m\binom{r}{2}=\binom{n}{2}\iff U=\Ptwo(V).
\end{equation}
$(\Leftarrow)$ take cardinalities. $(\Rightarrow)$ a finite subset whose
cardinality equals that of its superset is the whole set. Finally $U=\Ptwo(V)$
means every pair lies in some $\Ptwo(e)$, i.e.\ $p\subseteq e$ for some edge ---
precisely covering. Combining with \eqref{eq:seteq} gives the biconditional.
\end{proof}

\begin{remark}
$(\Leftarrow)$ recovers the classical ``Steiner $\Rightarrow$ equality.''
$(\Rightarrow)$ is new: no linear $r$-uniform hypergraph attains the packing
bound without being Steiner. The extremal family is characterized completely.
\end{remark}

\section{Local bound and its tightness}
For a vertex $v$ and $e\in L_v$, the erased edge $e\setminus\{v\}$ is an
$(r-1)$-subset of $V\setminus\{v\}$.

\begin{lemma}[Erased-edge disjointness]\label{lem:erased}
If $\E$ is linear, then for distinct $e,f\in L_v$ the sets $e\setminus\{v\}$ and
$f\setminus\{v\}$ are disjoint.
\end{lemma}
\begin{proof}
If $u\in(e\setminus\{v\})\cap(f\setminus\{v\})$ then $u,v\in e\cap f$ with
$u\ne v$, so $|e\cap f|\ge 2$, contradicting linearity.
\end{proof}

\begin{theorem}[Local packing bound]\label{thm:local}
For an $r$-uniform linear hypergraph and every vertex $v$,
$\deg(v)(r-1)\le n-1$.
\end{theorem}
\begin{proof}
The erased edges $\{e\setminus\{v\}\}_{e\in L_v}$ are pairwise disjoint
(Lemma~\ref{lem:erased}), each of size $r-1$, contained in $V\setminus\{v\}$ of
size $n-1$. Hence
$\deg(v)(r-1)=\bigl|\bigcup_{e\in L_v}(e\setminus\{v\})\bigr|\le n-1.$
\end{proof}

\begin{theorem}[Local tightness]\label{thm:localtight}
For an $r$-uniform linear hypergraph and a vertex $v$,
\[
  \deg(v)(r-1)=n-1\iff \text{the edges through }v\text{ cover every }u\ne v.
\]
\end{theorem}
\begin{proof}
The erased edges form a disjoint family inside $V\setminus\{v\}$ of total size
$\deg(v)(r-1)$. Equality with $n-1$ holds iff this family fills $V\setminus\{v\}$
(disjoint-fills-iff-sizes-match), i.e.\ every $u\ne v$ lies in some edge through
$v$ --- the link is covering.
\end{proof}

\section{Simultaneous global/local rigidity}
\begin{theorem}[Regularity]\label{thm:regular}
Let $\E$ be a covering $r$-uniform linear hypergraph on $n$ vertices, $r\ge 2$.
Then every vertex satisfies $\deg(v)(r-1)=n-1$, and hence
$\deg(v)=(n-1)/(r-1)$ for all $v$.
\end{theorem}
\begin{proof}
Covering means each pair $\{u,v\}$ lies in some edge, which contains $v$; thus
$L_v$ covers every $u\ne v$. By Theorem~\ref{thm:localtight},
$\deg(v)(r-1)=n-1$. As $n-1$ is independent of $v$, all degrees coincide.
\end{proof}

\begin{corollary}[Degrees-first edge count]\label{cor:count}
$\sum_{v\in V}\deg(v)=m\,r$, and with the uniform degree of
Theorem~\ref{thm:regular} over $n$ vertices, $m\,r\,(r-1)=n\,(n-1)$, which is
\eqref{eq:packing} at equality.
\end{corollary}

\section{Worked example: the Fano plane $S(2,3,7)$}
With $n=7$, $r=3$, $m=7$ and blocks
\[
  \{1,2,3\},\{1,4,5\},\{1,6,7\},\{2,4,6\},\{2,5,7\},\{3,4,7\},\{3,5,6\},
\]
each block holds $\binom{3}{2}=3$ pairs, pair-disjoint, covering $7\cdot 3=21$
pairs; since $\binom{7}{2}=21$, Theorem~\ref{thm:global} holds. Each point lies
on $3$ blocks, reaching $3\cdot 2=6=n-1$ vertices, so
Theorem~\ref{thm:localtight} holds; and every degree equals
$(n-1)/(r-1)=3$, as in Theorem~\ref{thm:regular}.

\section{Algorithms}
\textbf{A --- Linearity/packing certifier.} Verify $r$-uniformity and linearity,
accumulate covered pairs as a disjoint union, report
$m\binom{r}{2}=\binom{n}{2}$ and cross-check full coverage. Complexity
$O(m^2 r + m r^2)$.

\noindent\textbf{B --- Link/degree certifier.} For each $v$, erase $v$ from its
incident edges, check disjointness, and test $\deg(v)(r-1)=n-1$ against coverage
of $V\setminus\{v\}$; aggregate for Theorem~\ref{thm:regular}. Complexity
$O(n+mr+\sum_v\deg(v)^2)$.

\section{Discussion}
Linearity is the $e=2$ boundary of the BES extremal function; Theorem~\ref{thm:global}
characterizes its saturating hypergraphs exactly. The rigidity of
Theorem~\ref{thm:regular} explains why extremal density and perfect regularity
coincide for Steiner systems: both reformulate ``every pair covered exactly
once.'' Every result is one principle --- disjoint family fills iff sizes match
--- applied globally and locally.

\section{Future directions}
\begin{conjecture}[Near-extremal stability]
If $m\binom{r}{2}\ge\binom{n}{2}-t$, then the number of uncovered pairs is
$\binom{n}{2}-m\binom{r}{2}\le t$; stronger, at most $2t/(r-1)$ vertices fail
$\deg(v)(r-1)=n-1$.
\end{conjecture}
\begin{conjecture}[Resolvability]
Every partial parallel class (set of pairwise-disjoint edges) has size
$\le\lfloor n/r\rfloor$, with equality iff its edges partition $V$.
\end{conjecture}
\begin{conjecture}[Fisher-type bound]
For $S(2,r,n)$ with $r<n$, $m\ge n$, equivalently full point-rank; in stages,
$m=n(n-1)/(r(r-1))$ and $m\ge n\iff n\ge 2r-1$.
\end{conjecture}
\begin{conjecture}[Codegree threshold]
With $\deg(u,v)=|\{e:u,v\in e\}|$, $\sum_{u<v}\deg(u,v)=m\binom{r}{2}$ holds
without linearity, and linearity is equivalent to
$\sum\deg=\#\{\text{covered pairs}\}$.
\end{conjecture}
\begin{conjecture}[Linear Tur\'an-type density]
Extend the threshold to configurations spanning more than two vertices,
calibrating the interior of the BES landscape against the $e=2$ boundary here.
\end{conjecture}

\section{Conclusion}
The packing bound $m\binom{r}{2}\le\binom{n}{2}$ is an equality precisely for
Steiner systems (Theorem~\ref{thm:global}); the local bound is an equality
precisely when the link is covering (Theorem~\ref{thm:localtight}); and covering
hypergraphs are exactly those tight everywhere, with perfect regularity
(Theorem~\ref{thm:regular}). The whole theory rests on a single counting
principle, with the Fano plane $S(2,3,7)$ as the minimal simultaneously-tight
witness. All results have been formally verified.

